<template>
  <!--
    One root, two identities: a real router link when the tile has a
    destination, a plain <div> when it does not. RouterLink is registered
    LOCALLY (see `components`) so the tile does not depend on a global
    registration, and so it renders the <a href> a browser needs for
    middle-click and "open in new tab" — the reason this is a link and not a
    @click handler.
  -->
  <component
    :is="isLink ? 'RouterLink' : 'div'"
    class="kpi-card"
    :class="{ 'kpi-card--link': isLink }"
    :data-test="dataTest"
    :to="isLink ? linkTarget : undefined"
    :title="isLink && linkTitle ? linkTitle : undefined"
    @keydown.space="onSpace"
  >
    <div class="kpi-card-header">
      <span class="kpi-label">{{ label }}</span>
      <Icon :icon="icon" width="20" class="text-grey-5" />
    </div>
    <div class="kpi-value" data-test="touchless-kpi-value">{{ value }}</div>
    <div
      v-if="showDelta"
      class="kpi-delta"
      :class="deltaClass"
      data-test="touchless-kpi-delta"
    >
      {{ deltaLabel }}
    </div>
    <div v-if="subtitle" class="kpi-subtitle text-grey-6">{{ subtitle }}</div>
  </component>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { RouterLink, type RouteLocationRaw } from 'vue-router';
import { Icon } from '@iconify/vue';

/**
 * KPI tile for the Touchless dashboard.
 *
 * Copy of the DocNet `KpiWidget.vue` plus a `target` prop: when both `target`
 * and `numericValue` are given the tile shows the signed distance to the target
 * in percentage points, coloured green when the target is met and red when it
 * is missed. That colour is the whole point of the Ruiz 70% goal — a bare
 * number does not tell an AP lead whether they are on track.
 *
 * DOCB-14197: a tile may also be a drill-down to the documents behind its
 * number. Pass `to` and the tile becomes a link — focusable, hoverable, and a
 * real anchor, so middle-click and ctrl-click open the list in a new tab the
 * way every other link on the page does. Without `to` (or with `disabled`, the
 * count-is-zero case) it renders exactly as it always did, with no hover
 * affordance to promise a click that does nothing.
 */
export default defineComponent({
  name: 'TouchlessKpiCard',

  components: { Icon, RouterLink },

  props: {
    label: { type: String, required: true },
    value: { type: [String, Number], default: 0 },
    subtitle: { type: String, default: '' },
    icon: { type: String, default: 'mdi:information-outline' },
    /** Target in percent (0-100). Omit for tiles without a goal. */
    target: { type: Number, default: null },
    /** Numeric counterpart of `value`, used only for the delta calculation. */
    numericValue: { type: Number, default: null },
    dataTest: { type: String, default: '' },
    /** Drill-down destination. Omit to keep the tile inert. */
    to: {
      type: [Object, String] as PropType<RouteLocationRaw | null>,
      default: null,
    },
    /**
     * Suppress the link even though `to` was given — the tile's number is
     * zero, so the list behind it is empty and a link would only disappoint.
     */
    disabled: { type: Boolean, default: false },
    /** Tooltip / accessible hint for the link. Ignored when inert. */
    linkTitle: { type: String, default: '' },
  },

  computed: {
    linkTarget(): RouteLocationRaw | null {
      if (this.disabled) return null;
      return (this.to as RouteLocationRaw | null) ?? null;
    },

    isLink(): boolean {
      return this.linkTarget !== null;
    },

    showDelta(): boolean {
      return this.target !== null && this.numericValue !== null;
    },

    delta(): number {
      if (!this.showDelta) return 0;
      return (this.numericValue as number) - (this.target as number);
    },

    deltaClass(): string {
      return this.delta >= 0 ? 'kpi-delta--positive' : 'kpi-delta--negative';
    },

    deltaLabel(): string {
      const sign = this.delta >= 0 ? '+' : '';
      const rounded = Math.round(this.delta * 10) / 10;
      return this.$t('touchless_vs_target', {
        delta: `${sign}${rounded}`,
        target: this.target,
      }) as string;
    },
  },

  methods: {
    /**
     * Space activates the tile.
     *
     * Enter is left to the anchor — the browser already fires a click for it,
     * and a handler here would navigate twice. Space is the gap: on an `<a>` it
     * scrolls the page instead of activating, which on a card-shaped link reads
     * as broken.
     */
    onSpace(event: KeyboardEvent): void {
      const target = this.linkTarget;
      if (!target) return;
      event.preventDefault();
      void this.$router.push(target);
    },
  },
});
</script>

